h=load_history(); out=[]
for r in h:
 if r['family']!='spiral_classification' or '<' not in r['answer']: continue
 cs=[]
 for letter,chunk in re.findall(r'### Choice ([A-E])\s*(.*?)(?=### Choice [A-E]|## Your answer|\Z)',r['question'],re.S):
  def field(name):
   m=re.search(r'- '+re.escape(name)+r': ([^\n]+)',chunk); return m.group(1).strip() if m else None
  opt=field('Optimizer'); lr=field('Learning rate'); beta=field('Betas')
  if opt not in ['Adam','AdamW'] or not beta: continue
  cs.append((letter,opt,float(lr),float(beta.strip('[]').split(',')[1]),field('Weight decay'),tuple(field(x) for x in ['Depth','Width','Residual connections','Layer norm per layer','Activation','Initialization'])))
 for a,b in itertools.combinations(cs,2):
  if a[2]!=b[2] or a[3]==b[3] or a[5]!=b[5]: continue
  hi,lo=(a,b) if a[3]>b[3] else (b,a)
  m=re.search(r'training_steps: (\d+)',r['question']); t=int(m.group(1)) if m else None
  turns=re.search(r'spiral turns `([^`]+)',r['question'])
  out.append((r['question_id'],t,turns.group(1) if turns else '?',hi[:5],lo[:5],r['answer'].index(hi[0])<r['answer'].index(lo[0])))
